        # Calculate T_i and T_j
        for i in range(n):
            for j in range(n):
                if bp[i][j] == 1:
                    T_i[i][j] = Fraction(1)
                    T_j[j][i] = Fraction(1)

        entanglement = 0
        for i in range(n):
            for j in range(i, n):
                product = matrix_multiply(T_i[i], T_j[j])
                for k in range(n):
                    for l in range(n):
                        if abs(product[k][l]) > entanglement:
                            entanglement = abs(product[k][l])
        return entanglement

    def check_bp():
        n = random.randint(5, 40)
        bp = generate_bp(n)
        entanglement = free_probability_tensor_entanglement(bp, None)
